API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(Perimeter Router, "Perimeter Router", "Kubernetes Ingress / Istio", "Handles perimeter routing, TLS termination, and WAF.")
    Component(Token Exchange Service, "Token Exchange Service", "OAuth2/OIDC & JWT/PASETO", "Manages perimeter token exchange and fine-grained ABAC claims enforcement.")
}

Rel(Perimeter Router, Token Exchange Service, "Forwards requests for token validation and exchange", "HTTPS with MFA and ABAC")

@enduml

Patient Registration.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Patient Registration container

Container_Boundary(patient_registration, "Patient Registration") {
    Component(Admission_Controller, "Admission Controller", "Spring Boot Controller", "Handles public and internal patient admission requests routed from the API Gateway.")
    Component(Notification_Dispatcher, "Notification Dispatcher", "Spring Boot Service", "Dispatches asynchronous OTP and notification messages to external messaging brokers.")
    Component(Session_and_Rate_Limiter, "Session and Rate Limiter", "Spring Boot Component", "Interacts with Redis to enforce rate-limiting and manage user sessions during registration.")
}

Rel(Admission_Controller, Session_and_Rate_Limiter, "Validates sessions and enforces rate-limiting")
Rel(Admission_Controller, Notification_Dispatcher, "Triggers asynchronous notifications")
@enduml

Appointment Scheduling.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Appointment Scheduling container

Container_Boundary(appointment_scheduling, "Appointment Scheduling") {
    Component(Appointment_Controller, "Appointment Controller", "Spring Boot REST Controller", "Handles incoming appointment booking and scheduling requests from the API Gateway.")
    Component(Appointment_Service, "Appointment Service", "Spring Boot Service", "Contains business logic for appointment management and coordinates distributed locking.")
    Component(Event_Publisher, "Event Publisher", "Spring Kafka / AMQP Client", "Publishes asynchronous appointment events to the notification dispatcher.")
}

Rel(Appointment_Controller, Appointment_Service, "Delegates validated booking requests", "Java Method Invocation")
Rel(Appointment_Service, Event_Publisher, "Triggers async event publishing", "Kafka / AMQP")

@enduml

EMR Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(emr_service, "EMR Service") {
    Component(EMR_API_Controller, "EMR API Controller", "Spring Boot / REST", "Exposes clinical endpoints to handle patient electronic medical records requests securely.")
    Component(FHIR_Integration_Client, "FHIR Integration Client", "Spring Boot / HL7 FHIR", "Exchanges clinical data and lab results with external lab and imaging systems.")
    Component(Encryption_and_Audit_Service, "Encryption and Audit Service", "AES-256 / OpenTelemetry / FluentBit", "Enforces field-level encryption for PHI and handles asynchronous sidecar audit logging.")
}

Rel(EMR_API_Controller, Encryption_and_Audit_Service, "Enforces field-level encryption and logs requests")
Rel(EMR_API_Controller, FHIR_Integration_Client, "Delegates clinical data exchange")

@enduml
